from bisect import bisect_right
class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        tails = []
        for x in nums:
            y = -x
            pos = bisect_right(tails, y)
            if pos == len(tails):
                tails.append(y)
            else:
                tails[pos] = y
        return len(tails)

