class Solution {
    public int minimumOperations(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int x : nums) {
            int y = -x, lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails.get(mid) <= y) lo = mid + 1; else hi = mid;
            }
            if (lo == tails.size()) tails.add(y);
            else tails.set(lo, y);
        }
        return tails.size();
    }
}

