    const tails = [];
    const upperBound = (arr, y) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const m = (lo + hi) >> 1;
            if (arr[m] <= y) lo = m + 1; else hi = m; }
        return lo;
    };
    for (const x of nums) {
        const y = -x, pos = upperBound(tails, y);
        if (pos === tails.length) tails.push(y); else tails[pos] = y;
    }
    return tails.length;
};

